package com.nthexperience.desktop;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Follows the first-run permission-deferral test with a purchaser's broad in-app tour. */
public final class ElevenPurchaserSmoke extends Instrumentation {
 MainActivity home;View root;DesktopStore store;int checks;final StringBuilder visited=new StringBuilder("Area\tOrientation\tResult\n");
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle out=new Bundle();try{store=new DesktopStore(getTargetContext());check(getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).getBoolean("seen",false),"Follows completed first-run setup");home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();tap("Start menu");check(TenSmoke.find(root,StartMenu.class).isShown(),"Actual taskbar touch opens Start");shot("eleven-purchaser-start");ui(()->home.onBackPressed());ui(()->home.open("@settings"));TenSettings settings=TenSmoke.find(root,TenSettings.class);ui(()->window(settings).maximize());
  for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_PORTRAIT,ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE}){ui(()->home.setRequestedOrientation(orientation));waitForIdleSync();Thread.sleep(350);for(String[] category:TenSettingsCatalog.CATEGORIES){ui(()->{View target=TenSmoke.description(settings,"Settings category "+category[1]);check(target!=null&&target.performClick(),"Category navigation "+category[1]);check(settings.page.equals(category[0]),"Correct category content");});waitForIdleSync();visited.append(category[1]).append('\t').append(orientation).append("\tPASS\n");}for(TenSettingsCatalog.Page page:TenSettingsCatalog.PAGES){ui(()->{settings.navigate(page.id);check(settings.body.getChildCount()>0,"Content for "+page.title);});waitForIdleSync();visited.append(page.title).append('\t').append(orientation).append("\tPASS\n");}ui(()->settings.navigate("home"));shot(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?"eleven-purchaser-settings-portrait":"eleven-purchaser-settings-landscape");}
  ui(()->{settings.navigate("start");((Switch)TenSmoke.description(settings,"Hide name and profile picture on Start")).performClick();home.open("start-menu:");});check(store.prefs.getBoolean("eleven_start_hide_profile",false),"Start privacy choice committed");shot("eleven-purchaser-start-private");ui(()->home.onBackPressed());closeAll();
  for(String id:new String[]{"@computer","@files","@recycle","@notes","@sticky","@calendar","@weather","@clock","@photos",MediaLibrary.PLAYER,MediaLibrary.CENTER,"@taskmanager","@nota","@gadget:calculator","@gadget:converter","@gadget:puzzle","@gadget:dice","@welcome","@backup"}){ui(()->home.open(id));waitForIdleSync();Thread.sleep(100);DesktopWindow front=front();check(front!=null&&front.body!=null&&front.isShown(),"Usable built-in destination "+id);if(id.equals("@notes")){EditText note=(EditText)TenSmoke.description(front,"Notepad text");check(note!=null,"Notepad editor reachable");ui(()->note.setText("Purchaser walkthrough — saved draft"));}if(id.equals("@taskmanager")||id.equals("@nota")||id.equals("@gadget:calculator"))shot("eleven-purchaser-"+id.replace("@","").replace(":","-"));visited.append(id).append("\tlandscape\tPASS\n");ui(()->front.minimize());check(!front.isShown(),"Window minimizes: "+id);ui(()->home.open(id));check(front.isShown(),"Same tool restores: "+id);closeAll();}
  ui(()->home.open("@notes"));EditText note=(EditText)TenSmoke.description(root,"Notepad text");check(note!=null&&note.getText().toString().contains("Purchaser walkthrough"),"Notepad draft survives closing and reopening");closeAll();ui(()->home.open("@news"));waitForIdleSync();check(TenSmoke.description(root,"Widgets dashboard")!=null,"Widgets board opens");shot("eleven-purchaser-widgets");ui(()->home.onBackPressed());ui(()->home.open("@tenactions"));waitForIdleSync();shot("eleven-purchaser-notifications");ui(()->home.onBackPressed());ui(()->home.open("@taskview"));waitForIdleSync();shot("eleven-purchaser-taskview");ui(()->home.onBackPressed());
  ActivityMonitor monitor=addMonitor(MainActivity.class.getName(),null,false);ui(()->home.recreate());Activity next=waitForMonitorWithTimeout(monitor,12000);removeMonitor(monitor);check(next instanceof MainActivity,"Activity recreates after broad tour");home=(MainActivity)next;root=home.getWindow().getDecorView();waitForIdleSync();check(store.prefs.getBoolean("eleven_start_hide_profile",false),"Settings survive recreation");shot("eleven-purchaser-return");try(Writer report=new FileWriter(new File(getTargetContext().getFilesDir(),"eleven-purchaser-visits.tsv"))){report.write(visited.toString());}out.putString("stream","PASS: purchaser walkthrough "+checks+" assertions; real taskbar touch, every catalogued Settings page in portrait and landscape, deferred-access empty states, 19 built-in tools, minimize/restore, retained Notepad draft, Widgets/notifications/Task View and activity recreation. See screenshots and visited-page ledger.\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable error){try{shot("eleven-purchaser-failure");}catch(Exception ignored){}out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,out);}}
 void tap(String description)throws Exception{View target=TenSmoke.description(root,description);check(target!=null,"Control exists: "+description);Rect r=new Rect();ui(()->check(target.getGlobalVisibleRect(r),"Visible control: "+description));long t=SystemClock.uptimeMillis();for(int a:new int[]{0,1}){MotionEvent event=MotionEvent.obtain(t,SystemClock.uptimeMillis(),a,r.centerX(),r.centerY(),0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Touch injected");event.recycle();}waitForIdleSync();}
 DesktopWindow front(){final DesktopWindow[] value={null};walk(root,v->{if(v instanceof DesktopWindow&&v.isShown())value[0]=(DesktopWindow)v;});return value[0];}
 void walk(View v,java.util.function.Consumer<View> action){action.accept(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)walk(((ViewGroup)v).getChildAt(i),action);}
 void closeAll()throws Exception{ui(()->{List<DesktopWindow> windows=new ArrayList<>();walk(root,v->{if(v instanceof DesktopWindow)windows.add((DesktopWindow)v);});for(DesktopWindow window:windows)window.closeWindow();});waitForIdleSync();}
 DesktopWindow window(View v){while(v!=null&&!(v instanceof DesktopWindow))v=v.getParent() instanceof View?(View)v.getParent():null;check(v!=null,"Tool has a window");return (DesktopWindow)v;}
 void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(25,TimeUnit.SECONDS);}
 void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
 void shot(String name)throws Exception{waitForIdleSync();Thread.sleep(250);ui(()->{Bitmap image=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(image));try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+"-view.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new RuntimeException(e);}finally{image.recycle();}});Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}finally{image.recycle();}}}
}
